package api

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"testing"

	"github.com/luwa07832/service-discovery-api/internal/store"
)

type testServer struct {
	router http.Handler
	store  *store.Store
}

func newTestServer(t *testing.T) *testServer {
	t.Helper()
	st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return &testServer{router: NewRouter(st), store: st}
}

func (s *testServer) request(t *testing.T, method, target string, body any) *httptest.ResponseRecorder {
	t.Helper()
	var reader *bytes.Reader
	if body != nil {
		raw, err := json.Marshal(body)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		reader = bytes.NewReader(raw)
	} else {
		reader = bytes.NewReader(nil)
	}
	req := httptest.NewRequest(method, target, reader)
	req.Header.Set("Content-Type", "application/json")
	recorder := httptest.NewRecorder()
	s.router.ServeHTTP(recorder, req)
	return recorder
}

func decode(t *testing.T, recorder *httptest.ResponseRecorder) map[string]any {
	t.Helper()
	var out map[string]any
	if err := json.Unmarshal(recorder.Body.Bytes(), &out); err != nil {
		t.Fatalf("decode %q: %v", recorder.Body.String(), err)
	}
	return out
}

func registerBody(service, id, address string, healthy bool, weight float64, heartbeat string) map[string]any {
	return map[string]any{
		"service_name": service,
		"instance_id":  id,
		"address":      address,
		"healthy":      healthy,
		"weight":       weight,
		"heartbeat_at": heartbeat,
	}
}

func mustRegister(t *testing.T, s *testServer, body map[string]any) {
	t.Helper()
	recorder := s.request(t, http.MethodPost, "/api/v1/register", body)
	if recorder.Code != http.StatusOK {
		t.Fatalf("register status = %d body = %s", recorder.Code, recorder.Body.String())
	}
}

func TestHealthzReportsOK(t *testing.T) {
	s := newTestServer(t)
	recorder := s.request(t, http.MethodGet, "/healthz", nil)

	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d, want %d", recorder.Code, http.StatusOK)
	}
	if got := recorder.Body.String(); got != `{"database":"ok","status":"ok"}` {
		t.Fatalf("body = %s", got)
	}
}

func TestUnknownRouteUsesPublishedErrorShape(t *testing.T) {
	s := newTestServer(t)
	recorder := s.request(t, http.MethodGet, "/missing", nil)

	if recorder.Code != http.StatusNotFound {
		t.Fatalf("status = %d, want %d", recorder.Code, http.StatusNotFound)
	}
	errObj := decode(t, recorder)["error"].(map[string]any)
	if errObj["code"] != "route_not_found" {
		t.Fatalf("error = %v", errObj)
	}
}

func TestRegisterOverwriteAndPublicQueries(t *testing.T) {
	s := newTestServer(t)
	mustRegister(t, s, registerBody("svc", "i-1", "10.0.0.1:80", true, 5, "2026-10-01T10:00:00Z"))

	// Full record query.
	recorder := s.request(t, http.MethodGet, "/api/v1/services/svc/instances/i-1", nil)
	instance := decode(t, recorder)["instance"].(map[string]any)
	if instance["address"] != "10.0.0.1:80" || instance["healthy"] != true || instance["weight"] != float64(5) {
		t.Fatalf("instance = %v", instance)
	}
	if instance["heartbeat_at"] != "2026-10-01T10:00:00Z" {
		t.Fatalf("heartbeat = %v", instance["heartbeat_at"])
	}

	// Dedicated health, weight and heartbeat entries keep their public shape.
	health := decode(t, s.request(t, http.MethodGet, "/api/v1/services/svc/instances/i-1/health", nil))
	if health["healthy"] != true || health["health"] != "healthy" {
		t.Fatalf("health = %v", health)
	}
	weight := decode(t, s.request(t, http.MethodGet, "/api/v1/services/svc/instances/i-1/weight", nil))
	if weight["weight"] != float64(5) {
		t.Fatalf("weight = %v", weight)
	}
	heartbeat := decode(t, s.request(t, http.MethodGet, "/api/v1/services/svc/instances/i-1/heartbeat", nil))
	if heartbeat["heartbeat_at"] != "2026-10-01T10:00:00Z" {
		t.Fatalf("heartbeat = %v", heartbeat)
	}

	// Repeated registration overwrites the existing record.
	mustRegister(t, s, registerBody("svc", "i-1", "10.0.0.2:80", false, 7, "2026-10-01T10:05:00Z"))
	instance = decode(t, s.request(t, http.MethodGet, "/api/v1/services/svc/instances/i-1", nil))["instance"].(map[string]any)
	if instance["address"] != "10.0.0.2:80" || instance["healthy"] != false || instance["weight"] != float64(7) {
		t.Fatalf("overwritten instance = %v", instance)
	}
	list := decode(t, s.request(t, http.MethodGet, "/api/v1/services/svc/instances", nil))["instances"].([]any)
	if len(list) != 1 {
		t.Fatalf("list len = %d", len(list))
	}

	// Delete removes the record; second delete reports not found.
	if code := s.request(t, http.MethodDelete, "/api/v1/services/svc/instances/i-1", nil).Code; code != http.StatusOK {
		t.Fatalf("delete status = %d", code)
	}
	if code := s.request(t, http.MethodDelete, "/api/v1/services/svc/instances/i-1", nil).Code; code != http.StatusNotFound {
		t.Fatalf("second delete status = %d", code)
	}
}

func TestRegistrationValidationRejectsBadParameters(t *testing.T) {
	s := newTestServer(t)
	cases := []map[string]any{
		registerBody("", "i", "a", true, 1, "2026-10-01T10:00:00Z"),
		registerBody("svc", "", "a", true, 1, "2026-10-01T10:00:00Z"),
		registerBody("svc", "i", "a", true, -1, "2026-10-01T10:00:00Z"),
		registerBody("svc", "i", "a", true, 1, ""),
		registerBody("svc", "i", "a", true, 1, "2026-10-01T10:00:00Z"),
	}
	cases[4]["evaluate_at"] = "2026-10-01T09:59:59Z"

	for index, body := range cases {
		recorder := s.request(t, http.MethodPost, "/api/v1/register", body)
		if recorder.Code != http.StatusBadRequest {
			t.Fatalf("case %d: status = %d body = %s", index, recorder.Code, recorder.Body.String())
		}
		errObj := decode(t, recorder)["error"].(map[string]any)
		if errObj["code"] != "invalid_parameter" {
			t.Fatalf("case %d: code = %v", index, errObj["code"])
		}
	}
	list := decode(t, s.request(t, http.MethodGet, "/api/v1/services/svc/instances", nil))["instances"].([]any)
	if len(list) != 0 {
		t.Fatalf("invalid requests created %d records", len(list))
	}
}

func TestDiscoverFiltersAndSortsWithoutDeleting(t *testing.T) {
	s := newTestServer(t)
	evaluate := "2026-10-01T10:05:00Z"
	// Timeout 60s, deadline 2026-10-01T10:04:00Z.
	mustRegister(t, s, registerBody("svc", "fresh-high", "a", true, 10, "2026-10-01T10:04:30Z"))
	mustRegister(t, s, registerBody("svc", "fresh-low", "b", true, 1, "2026-10-01T10:04:30Z"))
	mustRegister(t, s, registerBody("svc", "same-weight-newer", "c", true, 5, "2026-10-01T10:04:20Z"))
	mustRegister(t, s, registerBody("svc", "same-weight-older", "d", true, 5, "2026-10-01T10:04:10Z"))
	mustRegister(t, s, registerBody("svc", "boundary", "e", true, 100, "2026-10-01T10:04:00Z"))
	mustRegister(t, s, registerBody("svc", "stale", "f", true, 100, "2026-10-01T10:03:00Z"))
	mustRegister(t, s, registerBody("svc", "unhealthy-fresh", "g", false, 100, "2026-10-01T10:04:59Z"))
	mustRegister(t, s, registerBody("other", "keep", "h", true, 1, "2026-10-01T10:04:30Z"))

	recorder := s.request(t, http.MethodGet,
		"/api/v1/discover?service_name=svc&evaluate_at="+evaluate+"&heartbeat_timeout=60", nil)
	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d body = %s", recorder.Code, recorder.Body.String())
	}
	instances := decode(t, recorder)["instances"].([]any)
	gotIDs := make([]string, 0, len(instances))
	for _, item := range instances {
		instance := item.(map[string]any)
		gotIDs = append(gotIDs, instance["instance_id"].(string))
		if _, ok := instance["address"]; !ok {
			t.Fatalf("entry missing address: %v", instance)
		}
		if _, ok := instance["healthy"]; !ok {
