	list := decode(t, s.request(t, http.MethodGet, "/api/v1/services/svc/instances", nil))["instances"].([]any)
	if len(list) != 7 {
		t.Fatalf("discovery mutated records: list len = %d", len(list))
	}
	// Other service is untouched.
	other := decode(t, s.request(t, http.MethodGet, "/api/v1/services/other/instances/keep", nil))["instance"]
	if other == nil {
		t.Fatalf("other service record missing after discovery")
	}

	// Unknown service and fully-filtered service both yield an empty list.
	unknown := decode(t, s.request(t, http.MethodGet,
		"/api/v1/discover?service_name=nope&evaluate_at="+evaluate+"&heartbeat_timeout=60", nil))["instances"].([]any)
