	empty := decode(t, s.request(t, http.MethodGet,
		"/api/v1/discover?service_name=other&evaluate_at=2026-10-01T11:00:00Z&heartbeat_timeout=60", nil))["instances"].([]any)
	if len(empty) != 0 {
		t.Fatalf("fully filtered service returned %d instances", len(empty))
	}
}

