		"service_name": "svc-a", "instance_id": "i-unhealthy",
		"healthy": false, "weight": 100, "heartbeat_at": "2026-10-01T11:59:59Z",
	})
	registerInstance(t, router, map[string]any{
		"service_name": "svc-a", "instance_id": "i-lost",
		"healthy": true, "weight": 100, "heartbeat_at": "2026-10-01T11:59:00Z",
	})
	registerInstance(t, router, map[string]any{
		"service_name": "svc-b", "instance_id": "i-other",
		"healthy": true, "weight": 1, "heartbeat_at": "2026-10-01T11:59:59Z",
	})

	// Deadline 11:59:30: i-lost is exactly at the deadline and must be removed;
	// i-unhealthy is removed as unhealthy.
	code, response := discover(t, router,
		"service_name=svc-a&evaluate_at=2026-10-01T12:00:00Z&heartbeat_timeout=30s")
	if code != http.StatusOK {
		t.Fatalf("discover status = %d", code)
	}
	instances := response["instances"].([]any)
	if len(instances) != 2 {
		t.Fatalf("got %d candidates: %v", len(instances), instances)
	}
	first := instances[0].(map[string]any)
	second := instances[1].(map[string]any)
	// Weight descending wins over heartbeat recency.
	if first["instance_id"] != "i-high" || second["instance_id"] != "i-low" {
		t.Fatalf("order = %s, %s", first["instance_id"], second["instance_id"])
	}

	// The lost instance is still queryable: discovery never deletes records.
	lost := doRequest(t, router, http.MethodGet, "/api/v1/services/svc-a/instances/i-lost", nil)
	if lost.Code != http.StatusOK {
		t.Fatalf("lost instance removed from storage: status = %d", lost.Code)
	}

