		"service_name": "svc-c", "instance_id": "a-second-newer",
		"healthy": true, "weight": 3, "heartbeat_at": "2026-10-01T11:59:45Z",
	})
	_, response = discover(t, router,
		"service_name=svc-c&evaluate_at=2026-10-01T12:00:00Z&heartbeat_timeout=30s")
	ordered := response["instances"].([]any)
	if ordered[0].(map[string]any)["instance_id"] != "a-second-newer" ||
		ordered[1].(map[string]any)["instance_id"] != "b-second" {
		t.Fatalf("tie-break order wrong: %v", ordered)
	}

	registerInstance(t, router, map[string]any{
		"service_name": "svc-d", "instance_id": "z-first",
		"healthy": true, "weight": 2, "heartbeat_at": "2026-10-01T11:59:45Z",
	})
	registerInstance(t, router, map[string]any{
		"service_name": "svc-d", "instance_id": "a-later",
		"healthy": true, "weight": 2, "heartbeat_at": "2026-10-01T11:59:45Z",
	})
	_, response = discover(t, router,
		"service_name=svc-d&evaluate_at=2026-10-01T12:00:00Z&heartbeat_timeout=30s")
	ordered = response["instances"].([]any)
	if ordered[0].(map[string]any)["instance_id"] != "a-later" ||
		ordered[1].(map[string]any)["instance_id"] != "z-first" {
		t.Fatalf("instance id tie-break wrong: %v", ordered)
	}

	// Unknown service yields an empty list, not an error.
	code, response = discover(t, router,
		"service_name=svc-none&evaluate_at=2026-10-01T12:00:00Z&heartbeat_timeout=30s")
	if code != http.StatusOK || len(response["instances"].([]any)) != 0 {
		t.Fatalf("unknown service: code=%d body=%v", code, response)
	}
}

