	if status != http.StatusOK || len(body["instances"].([]any)) != 4 {
		t.Fatalf("health query healthy=true: status=%d body=%v", status, body)
	}
	status, body = doRequest(t, http.MethodGet, server.URL+"/api/v1/services/svc/instances?healthy=false", nil)
	if status != http.StatusOK || len(body["instances"].([]any)) != 1 {
		t.Fatalf("health query unhealthy: status=%d body=%v", status, body)
	}

	// Discovery is scoped to the requested service.
	status, body = discover(t, server.URL, "other", "2026-10-01T12:00:00Z", 3600)
	if status != http.StatusOK || len(body["instances"].([]any)) != 1 {
		t.Fatalf("other service discover: status=%d body=%v", status, body)
	}

	// Unknown and emptied services return an empty list, never null.
	status, body = discover(t, server.URL, "ghost", "2026-10-01T12:00:00Z", 60)
	if status != http.StatusOK || len(body["instances"].([]any)) != 0 {
		t.Fatalf("unknown service discover: status=%d body=%v", status, body)
	}
}

