func TestValidationErrorsDoNotMutateRecords(t *testing.T) {
	server, cleanup := newTestServer(t)
	defer cleanup()
	good := map[string]any{"service_name": "svc", "instance_id": "keep", "address": "a:1", "healthy": true, "weight": 7, "heartbeat_at": "2026-10-01T12:00:00Z"}
	if status, _ := register(t, server.URL, good); status != http.StatusOK {
		t.Fatalf("register good: %d", status)
	}

	badBodies := []map[string]any{
		{"service_name": "", "instance_id": "i", "weight": 1, "heartbeat_at": "2026-10-01T12:00:00Z"},
		{"service_name": "svc", "instance_id": "", "weight": 1, "heartbeat_at": "2026-10-01T12:00:00Z"},
		{"service_name": "svc", "instance_id": "i", "weight": -1, "heartbeat_at": "2026-10-01T12:00:00Z"},
		{"service_name": "svc", "instance_id": "i", "weight": "x", "heartbeat_at": "2026-10-01T12:00:00Z"},
		{"service_name": "svc", "instance_id": "i", "weight": 1},
		{"service_name": "svc", "instance_id": "i", "weight": 1, "heartbeat_at": "not-a-time"},
	}
	for _, body := range badBodies {
		status, decoded := register(t, server.URL, body)
		if status != http.StatusBadRequest {
			t.Fatalf("status = %d for %v, want 400", status, body)
		}
		errObject := decoded["error"].(map[string]any)
		if errObject["code"] != "invalid_parameter" {
			t.Fatalf("error code = %v", errObject["code"])
		}
	}

	// Failed update must not overwrite the existing record.
	status, body := doRequest(t, http.MethodPut, server.URL+"/api/v1/services/svc/instances/keep",
		map[string]any{"weight": -5, "heartbeat_at": "2026-10-01T13:00:00Z"})
	if status != http.StatusBadRequest {
		t.Fatalf("bad update status = %d", status)
	}
	status, body = doRequest(t, http.MethodGet, server.URL+"/api/v1/services/svc/instances/keep", nil)
	record := body["instance"].(map[string]any)
	if record["weight"].(float64) != 7 || record["address"] != "a:1" {
		t.Fatalf("record mutated by failed update: %v", record)
	}

	// Failed delete must not delete anything.
	status, _ = doRequest(t, http.MethodDelete, server.URL+"/api/v1/services//instances/keep", nil)
	if status != http.StatusBadRequest {
		t.Fatalf("delete empty service status = %d, want 400", status)
	}
	status, _ = doRequest(t, http.MethodGet, server.URL+"/api/v1/services/svc/instances/keep", nil)
	if status != http.StatusOK {
		t.Fatalf("record missing after failed delete: %d", status)
	}

	// Invalid discovery parameters.
	invalidDiscover := []string{
		"/api/v1/discover?service_name=&evaluate_at=2026-10-01T12:00:00Z&heartbeat_timeout=60",
		"/api/v1/discover?service_name=svc&heartbeat_timeout=60",
		"/api/v1/discover?service_name=svc&evaluate_at=2026-10-01T12:00:00Z&heartbeat_timeout=0",
		"/api/v1/discover?service_name=svc&evaluate_at=2026-10-01T12:00:00Z&heartbeat_timeout=-5",
	}
	for _, path := range invalidDiscover {
		status, body := doRequest(t, http.MethodGet, server.URL+path, nil)
		if status != http.StatusBadRequest {
			t.Fatalf("%s status=%d, want 400 (%v)", path, status, body)
		}
	}
	// Evaluation point earlier than an instance heartbeat.
	status, body = doRequest(t, http.MethodGet,
		server.URL+"/api/v1/discover?service_name=svc&evaluate_at=2026-10-01T11:00:00Z&heartbeat_timeout=60", nil)
	if status != http.StatusBadRequest {
		t.Fatalf("clock-skew discover status=%d body=%v", status, body)
	}
	// Unknown service with clock-skew params stays an empty result.
	status, body = doRequest(t, http.MethodGet,
		server.URL+"/api/v1/discover?service_name=ghost&evaluate_at=2000-01-01T00:00:00Z&heartbeat_timeout=60", nil)
	if status != http.StatusOK || len(body["instances"].([]any)) != 0 {
		t.Fatalf("unknown service with old evaluate_at: status=%d body=%v", status, body)
	}
}

