	server, cleanup := newTestServer(t)
	defer cleanup()
	instance := map[string]any{"service_name": "svc", "instance_id": "i-1", "address": "a:1", "healthy": true, "weight": 3, "heartbeat_at": "2026-10-01T12:00:00Z"}
